dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "region",
      "label": "Gene or Region",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true"
    },
    {
      "parameter": "phenotype1",
      "label": "Phenotype 1",
      "type": "input"
    },
    {
      "parameter": "phenotype2",
      "label": "Phenotype 2",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "top_associations",
      "header": "Top-associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "top-associations",
        "parameters": [
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Lead Variant(CHR:POS:REF:ALT)",
            "raw field": "varId"
          },
          {
            "type": "raw",
            "field name": "dbSNP",
            "raw field": "dbSNP"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Phenotype 1",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Phenotype 2",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Lead Variant(CHR:POS:REF:ALT)",
          "dbSNP",
          "P-Value",
          "Beta",
          "Phenotype",
          "Phenotype 1",
          "Phenotype 2"
        ],
        "locus field": "Lead Variant(CHR:POS:REF:ALT)",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ]
          },
          "Lead Variant(CHR:POS:REF:ALT)": {
            "type": [
              "link"
            ],
            "link to": "/variant.html?variant=",
            "new tab": "true"
          },
          "dbSNP": {
            "type": [
              "link"
            ],
            "link to": "/variant.html?variant=",
            "new tab": "true"
          },
          "Phenotype": {
            "type": [
              "kp phenotype link"
            ],
            "link to": "/phenotype.html?phenotype=",
            "new tab": "true"
          },
          "Phenotype 1": {
            "type": [
              "set parameter"
            ],
            "parameter": "phenotype1"
          },
          "Phenotype 2": {
            "type": [
              "set parameter"
            ],
            "parameter": "phenotype2"
          },
          "Beta": {
            "type": [
              "direction triangle"
            ]
          }
        }
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "phenotype group",
        "y axis field": "P-Value",
        "convert y -log10": "true",
        "y ticks decimal point": "2",
        "phenotype map": "kp phenotype map",
        "render by": "Phenotype",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Beta",
        "beta field": "Beta",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "thresholds": [
          "5e-8"
        ],
        "height": 500
      }
    },
    {
      "section id": "associations1",
